<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import './release.css'
const emit=defineEmits(['unread'])
const device=ref(sessionStorage.getItem('sisu-push-device')||'')
const rows=ref([]),config=ref(null),count=ref(0),page=ref(0),error=ref(''),busy=ref(false),note=ref('')
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const result=await Promise.all([request('notification_service','inbox',{page:page.value}),request('release','channels',{},'GET'),request('release','unread',{},'GET')]);rows.value=result[0];config.value=result[1];count.value=result[2].count;emit('unread',count.value)}
async function read(n){await run(async()=>{await request('notification_service','mark_read',{name:n.name});await load()})}
async function save(){await run(async()=>{await request('notification_service','save_preferences',{settings:{...config.value.settings,channels:config.value.preferences}});note.value='Preferences saved. Verified contact details and provider delivery rules still apply.'})}
async function push(){await run(async()=>{if(!config.value.browser_push_available||typeof window.sisuPushAdapter?.register!=='function')throw Error('Browser push adapter is not installed/configured. No token was registered.');const result=await window.sisuPushAdapter.register();const saved=await request('devices','register',{device_id:result.device_id,token:result.token,platform:'web'});device.value=saved.device;sessionStorage.setItem('sisu-push-device',saved.device);note.value='Device token registered. Provider delivery acceptance still requires testing.'})}
async function revoke(){await run(async()=>{await request('devices','revoke',{device:device.value});device.value='';sessionStorage.removeItem('sisu-push-device');note.value='Device token revoked on this site.'})}
onMounted(()=>run(load))
</script>
<template><section class="release"><h1>Notifications <span class="badge">{{count}} unread</span></h1><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="note" role="status">{{note}}</p><p v-if="busy" role="status">Loading…</p><button class="button subtle" :disabled="busy" @click="run(load)">Refresh</button><article v-for="n in rows" :key="n.name" class="panel"><p>{{n.body}}</p><small>{{n.event_type}} · {{n.creation}} · {{n.read_at?'Read':'Unread'}}</small><button v-if="!n.read_at" class="button subtle" :disabled="busy" @click="read(n)">Mark read</button></article><p v-if="!busy&&!rows.length">No notifications on this page.</p><button class="button subtle" :disabled="busy||page===0" @click="page--;run(load)">Previous</button><button class="button subtle" :disabled="busy||rows.length<50" @click="page++;run(load)">Next</button><form v-if="config" class="panel" @submit.prevent="save"><h2>Delivery preferences</h2><label v-for="(available,c) in config.available" :key="c" class="check"><input type="checkbox" v-model="config.preferences[c]" :disabled="!available">{{c}} · {{available?'Configured and entitled':'Unavailable — configuration or plan required'}}</label><p>Email/WhatsApp also require verified contact details and contact consent in Settings. Configured does not mean provider-tested.</p><button class="button primary" :disabled="busy">Save preferences</button><button type="button" class="button subtle" :disabled="busy||!config.browser_push_available" @click="push">Register this browser for push</button><button v-if="device" type="button" class="button subtle" :disabled="busy" @click="revoke">Revoke this browser token</button></form></section></template>
